// Output: what a compile is written as, file name -> content (Write); the
// caller writes them (the CLI to a directory, a server to git).
package fsio

import (
	"bytes"
	"cmp"
	"fmt"
	"maps"
	"regexp"
	"slices"
	"strings"
	"unicode"

	"go.yaml.in/yaml/v3"

	"github.com/okdp/okdp-compiler/internal/chart"
	"github.com/okdp/okdp-compiler/internal/okdp"
)

// DefaultIndent: the indentation of the YAML files, in spaces.
const DefaultIndent = 2

// generated: the first line of the values files and of the install script
// (after its #!), Go's mark of a generated file, which GitHub, linters and
// editors know.
const generated = "# Code generated by okdp-compile. DO NOT EDIT.\n"

// Output: the files Write gives for a compile, as the flags of
// okdp-compile choose them.
type Output struct {
	Umbrella     bool // --umbrella: the instance as one chart (umbrella), instead of a values file per chart (valuesFiles)
	Install      bool // --mkinstall: InstallScript, which installs them (install, or installUmbrella)
	Dependencies bool // --mkdag: DependenciesFile
	Indent       int  // --indent: the indentation of the YAML files, 2 to 9 spaces; 0: DefaultIndent
}

// Write: what `okdp-compile -o <dir>` writes for res with the options o,
// file name -> content: the values of each chart (valuesFiles), or the
// instance as one chart (umbrella); then InstallScript and
// DependenciesFile, when o asks for them. A Result built by a caller is
// checked first: each key one the outputs can name (resultKey), its
// upstream chart in Result.Charts.
func Write(res *okdp.Result, o Output) (map[string][]byte, error) {
	indent := cmp.Or(o.Indent, DefaultIndent)
	// What yaml.v3 writes: it would take any other value as 2.
	if indent < 2 || indent > 9 {
		return nil, fmt.Errorf("Output.Indent %d: 2 to 9 spaces, 0 for DefaultIndent", o.Indent)
	}
	for _, key := range slices.Sorted(maps.Keys(res.Values)) {
		if !resultKey.MatchString(key) {
			return nil, fmt.Errorf("chart %q: a key of the result names a file (<key>.values.yaml) and an umbrella dependency alias: letters, digits, - and _", key)
		}
		if _, ok := res.Charts[key]; !ok {
			return nil, fmt.Errorf("chart %q: not in Result.Charts, the upstream chart that renders its values", key)
		}
	}
	write, script := valuesFiles, install
	if o.Umbrella {
		write, script = umbrella, installUmbrella
	}
	files, err := write(res, indent)
	if err != nil {
		return nil, err
	}
	if o.Install {
		if files[InstallScript], err = script(res); err != nil {
			return nil, err
		}
	}
	if o.Dependencies {
		if files[DependenciesFile], err = marshal(res.Dependencies, indent); err != nil {
			return nil, err
		}
	}
	return files, nil
}

// DependenciesFile: Result.Dependencies as a YAML list, [] when there is
// none (Output.Dependencies): the instances the connection references
// point to, for a deployer that orders the releases (Flux dependsOn, Argo
// CD sync waves).
const DependenciesFile = "okdp.dependencies.yaml"

// IsOutputFile: name is a file Write gives, in any mode: <key>.values.yaml
// (valuesFiles), umbrellaChartFile and UmbrellaValues (umbrella),
// InstallScript, DependenciesFile. A caller that keeps the files of an instance in a directory may
// remove those a compile no longer gives, and no other.
func IsOutputFile(name string) bool {
	switch name {
	case umbrellaChartFile, UmbrellaValues, InstallScript, DependenciesFile:
		return true
	}
	return strings.HasSuffix(name, ".values.yaml")
}

// resultKey: a chart key as the outputs name it: a file
// (<key>.values.yaml) and an umbrella dependency alias, letters, digits, -
// and _ (Helm's rule for an alias). The keys of a compile follow it (DNS
// labels, chart.Specs.Check, and the compiler's): Write refuses the others,
// in a Result built by a caller.
var resultKey = regexp.MustCompile(`^[a-zA-Z0-9_-]+$`)

// valuesFiles: <key>.values.yaml, the final values of each chart, OKDP's
// own objects among them (okdp.values.yaml, the values of the okdp chart),
// marked generated (valuesFile), the next line naming the upstream chart
// that renders them (chartComment), indented by indent spaces.
func valuesFiles(res *okdp.Result, indent int) (map[string][]byte, error) {
	files := map[string][]byte{}
	for _, key := range slices.Sorted(maps.Keys(res.Values)) {
		comment, err := chartComment(key, res.Charts[key])
		if err != nil {
			return nil, err
		}
		b, err := valuesFile(res.Values[key], comment, indent)
		if err != nil {
			return nil, err
		}
		files[key+".values.yaml"] = b
	}
	return files, nil
}

// chartComment: the comment line that names the upstream chart ref of the
// chart key, as Helm takes it (chartArgs, each shell-quoted): the words
// between `helm template <release>` and `-f <key>.values.yaml`. A control
// character, which would end the comment, fails.
func chartComment(key string, ref chart.Ref) (string, error) {
	args := chartArgs(ref)
	for i, a := range args {
		if strings.ContainsFunc(a, unicode.IsControl) {
			return "", fmt.Errorf("chart %q: its upstream chart in Result.Charts holds a control character: %q", key, a)
		}
		args[i] = shellWord(a)
	}
	return "# Chart: " + strings.Join(args, " ") + "\n", nil
}

// chartArgs: the arguments that name ref to Helm: oci://<repository>/<chart>
// for a registry, <chart> --repo <repository> otherwise, then --version
// <version>.
func chartArgs(ref chart.Ref) []string {
	args := []string{ref.Chart, "--repo", ref.Repository}
	if strings.HasPrefix(ref.Repository, "oci://") {
		args = []string{strings.TrimSuffix(ref.Repository, "/") + "/" + ref.Chart}
	}
	return append(args, "--version", ref.Version)
}

// valuesFile: v as a values file, its first line generated, then the
// comment lines of header, indented by indent spaces (marshal).
func valuesFile(v any, header string, indent int) ([]byte, error) {
	b, err := marshal(v, indent)
	if err != nil {
		return nil, err
	}
	return append([]byte(generated+header), b...), nil
}

// marshal: v as a YAML document indented by indent spaces, 2 to 9 (checked
// by Write).
func marshal(v any, indent int) ([]byte, error) {
	var buf bytes.Buffer
	enc := yaml.NewEncoder(&buf)
	enc.SetIndent(indent)
	if err := enc.Encode(v); err != nil {
		return nil, err
	}
	if err := enc.Close(); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}
